#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 63
#define MAX_ROMAN_VAL 3999

static const int values[] = {1000,900,500,400,100,90,50,40,10,9,5,4,1};
static const char *symbols[] = {"M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"};
#define NUM_TOKENS (sizeof(values)/sizeof(values[0]))

static int digit_value(char c){
    switch(c){
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default: return 0;
    }
}

static void int_to_roman(int n, char *out){
    char *p = out;
    for(size_t i=0;i<NUM_TOKENS;++i){
        while(n >= values[i]){
            const char *sym = symbols[i];
            while(*sym) *p++ = *sym++;
            n -= values[i];
        }
    }
    *p = '\0';
}

static int roman_to_int(const char *s, int *result){
    size_t len = strlen(s);
    if(len==0) return -1;
    int total = 0;
    int prev = 0;
    for(ssize_t i = (ssize_t)len-1; i>=0; --i){
        int cur = digit_value(s[i]);
        if(cur==0) return -1;
        if(cur < prev) total -= cur; else total += cur;
        prev = cur;
    }
    if(total <= 0 || total > MAX_ROMAN_VAL) return -1;
    *result = total;
    return 0;
}

int main(int argc, char **argv){
    if(argc < 2){
        puts("INVALID");
        return 0;
    }
    const char *input = argv[1];
    size_t in_len = strlen(input);
    if(in_len == 0 || in_len > MAX_INPUT_LEN){
        puts("INVALID");
        return 0;
    }
    char upper[MAX_INPUT_LEN+1];
    for(size_t i=0;i<in_len;++i){
        char c = input[i];
        if('a' <= c && c <= 'z') c = c - ('a' - 'A');
        upper[i] = c;
    }
    upper[in_len] = '\0';
    int value;
    if(roman_to_int(upper, &value) != 0){
        puts("INVALID");
        return 0;
    }
    char canonical[32];
    int_to_roman(value, canonical);
    if(strcmp(upper, canonical) != 0){
        puts("INVALID");
        return 0;
    }
    printf("%d\n", value);
    return 0;
}
